// 가이드의 Reporter 예제에 추가한 일괄 업데이트:
// 여러 값을 다 바꾼 뒤 한 번만 보고해, 어긋난 중간 상태가 전송되지 않게 한다
public void UpdateState(System.Action<SpoilerReporter> updateAction)
{
    isBatching = true;
    updateAction?.Invoke(this);
    isBatching = false;
    Report();
}

public void SetRoom(ERoom newRoom, string newRoomID = "")
{
    if (Room == newRoom && RoomID == newRoomID) return;
    room = newRoom;
    roomID = newRoomID;
    if (!isBatching) Report();
}

// 사용처: 포탈로 방을 옮길 때 (키 · 값은 제너레이터가 만든 Enum)
